# apr2000.sav -- Gallup, 14 demographic variables
survey(
  survey_id = "apr2000.sav",
  source    = "Gallup",
  file_name = "apr2000.sav",
  demographics = function(..d) {
    ..d %>% transmute(
      # age <- yrbirth | YEAR OF BIRTH
      age = recode_values(as.numeric(..d[["yrbirth"]]), 1910 ~ 90, 1912 ~ 88, 1913 ~ 87, 1914 ~ 86, 1915 ~ 85, 1916 ~ 84, 1917 ~ 83, 1918 ~ 82, 1919 ~ 81, 1920 ~ 80, 1921 ~ 79, 1922 ~ 78, 1923 ~ 77, 1924 ~ 76, 1925 ~ 75, 1926 ~ 74, 1927 ~ 73, 1928 ~ 72, 1929 ~ 71, 1930 ~ 70, 1931 ~ 69, 1932 ~ 68, 1933 ~ 67, 1934 ~ 66, 1935 ~ 65, 1936 ~ 64, 1937 ~ 63, 1938 ~ 62, 1939 ~ 61, 1940 ~ 60, 1941 ~ 59, 1942 ~ 58, 1943 ~ 57, 1944 ~ 56, 1945 ~ 55, 1946 ~ 54, 1947 ~ 53, 1948 ~ 52, 1949 ~ 51, 1950 ~ 50, 1951 ~ 49, 1952 ~ 48, 1953 ~ 47, 1954 ~ 46, 1955 ~ 45, 1956 ~ 44, 1957 ~ 43, 1958 ~ 42, 1959 ~ 41, 1960 ~ 40, 1961 ~ 39, 1962 ~ 38, 1963 ~ 37, 1964 ~ 36, 1965 ~ 35, 1966 ~ 34, 1967 ~ 33, 1968 ~ 32, 1969 ~ 31, 1970 ~ 30, 1971 ~ 29, 1972 ~ 28, 1973 ~ 27, 1974 ~ 26, 1975 ~ 25, 1976 ~ 24, 1977 ~ 23, 1978 ~ 22, 1979 ~ 21, 1980 ~ 20, 1981 ~ 19, 1982 ~ 18),
      # age_cats <- age | constructed from continuous age
      age_cats = recode_values(as.numeric(age), 0:29 ~ 1, 30:49 ~ 2, 50:125 ~ 3),
      # degree <- educ x grad | HIGHEST LEVEL EDUCATION ATTAINED
      degree = pair_recode(..d[["educ"]], ..d[["grad"]], c("10|1" = 0, "10|2" = 0, "10|3" = 0, "4|NA" = 0, "6|1" = 0, "6|2" = 0, "7|1" = 0, "7|2" = 0, "7|3" = 0, "8|1" = 1, "8|2" = 0, "9|1" = 0, "9|2" = 0, "9|3" = 0)),
      # gender <- sex | GENDER
      gender = recode_values(as.numeric(..d[["sex"]]), 1 ~ 0, 2 ~ 1),
      # mother_tongue <- mtongue | MOTHER TONGUE
      mother_tongue = recode_values(as.numeric(..d[["mtongue"]]), 1 ~ 4, 6 ~ 2, 7 ~ 1),
      # occupation <- occup | OCCUPATION
      occupation = recode_values(as.numeric(..d[["occup"]]), 1 ~ 99, 4 ~ 8, 5 ~ 7, 6 ~ 9, 7 ~ 99, 8 ~ 2, 9 ~ 1, 10:11 ~ 3, 12:13 ~ 4),
      # province <- prov | PROVINCIAL AREA
      province = recode_values(as.numeric(..d[["prov"]]), 1 ~ 48, 2:3 ~ 59, 4 ~ 46, 5 ~ 13, 6 ~ 10, 7 ~ 12, 8:9 ~ 35, 10:11 ~ 24, 12 ~ 47, 13 ~ 11),
      # region <- prov | PROVINCIAL AREA
      region = recode_values(as.numeric(..d[["prov"]]), 1 ~ 4, 2:3 ~ 5, 4 ~ 4, 5:7 ~ 1, 8:9 ~ 3, 10:11 ~ 2, 12 ~ 4, 13 ~ 1),
      # religion <- religion | RELIGIOUS PREFERENCE
      religion = recode_values(as.numeric(..d[["religion"]]), 1 ~ 4, 2 ~ 99, 4 ~ 5, 6 ~ 2, 7 ~ 3, 8 ~ 1),
      # survey_mode <- assigned by hand | assigned by hand; not in the survey file
      survey_mode = rep(3, nrow(..d)),
      # union_household <- union | YOU OR SPOUSE LABOUR UNION MEMBER
      union_household = recode_values(as.numeric(..d[["union"]]), 1:3 ~ 1, 4 ~ 0),
      # vote_intention <- nowparty | YOU'D VOTE FOR IN FEDERAL ELECTION
      vote_intention = recode_values(as.numeric(..d[["nowparty"]]), 1 ~ 9, 2 ~ 99, 3 ~ 98, 4 ~ 99, 6 ~ 97, 7 ~ 1, 8 ~ 2, 9 ~ 3, 10 ~ 8, 11 ~ 6, 12 ~ 8),
      # language <- mother_tongue | mother tongue (no language-at-home question in this survey)
      language = in_range(mother_tongue, 1, 99),
      # language_var <- mother_tongue | which source supplied language: 2 = mother tongue
      language_var = recode_values(as.numeric(mother_tongue), 1:99 ~ 2)
    )
  }
)

# aug1951_212.sav -- Gallup, 11 demographic variables
survey(
  survey_id = "aug1951_212.sav",
  source    = "Gallup",
  file_name = "aug1951_212.sav",
  demographics = function(..d) {
    ..d %>% transmute(
      # com_100 <- commsize | SIZE OF COMMUNITY
      com_100 = recode_values(as.numeric(..d[["commsize"]]), 1:4 ~ 0, 5 ~ 1),
      # gender <- sex | SEX
