      # language_home <- mtongue | LANGUAGE SPOKEN
      language_home = recode_values(as.numeric(..d[["mtongue"]]), 1 ~ 2, 2 ~ 1, 3 ~ 3),
      # language_var <- language_home | which source supplied language: 1 = spoken at home
      language_var = recode_values(as.numeric(language_home), 1:99 ~ 1),
      # occupation <- occup | OCCUPATION
      occupation = recode_values(as.numeric(..d[["occup"]]), 0 ~ 6, 1 ~ 2, 2:3 ~ 1, 4 ~ 3, 5 ~ 99, 6:8 ~ 4, 9 ~ 5, 10 ~ 9, 11 ~ 99),
      # province <- prov | RESIDENT PROVINCE
      province = recode_values(as.numeric(..d[["prov"]]), 0 ~ 10, 1 ~ 11, 2 ~ 12, 3 ~ 13, 4 ~ 24, 5 ~ 35, 6 ~ 46, 7 ~ 47, 8 ~ 48, 9 ~ 59),
      # region <- prov | RESIDENT PROVINCE
      region = recode_values(as.numeric(..d[["prov"]]), 0:3 ~ 1, 4 ~ 2, 5 ~ 3, 6:8 ~ 4, 9 ~ 5),
      # survey_mode <- assigned by hand | assigned by hand; not in the survey file
      survey_mode = rep(1, nrow(..d)),
      # vote_choice <- lparty | PARTY VOTED FOR LAST FEDERAL ELECTION
      vote_choice = recode_values(as.numeric(..d[["lparty"]]), 0 ~ 98, 1 ~ 2, 2 ~ 1, 3 ~ 3, 4 ~ 4, 5 ~ 5, 6 ~ 9, 7 ~ 99),
      # vote_intention <- nowparty | PRESENT PREFERRED POLITICAL PARTY
      vote_intention = recode_values(as.numeric(..d[["nowparty"]]), 0 ~ 98, 1 ~ 2, 2 ~ 1, 3 ~ 3, 4 ~ 4, 5 ~ 5, 6 ~ 9, 7 ~ 99),
      # language <- language_home | language spoken at home
      language = in_range(language_home, 1, 99)
    )
  }
)

