  survey_id = "cipo-337-E-1969-09_F1.sav",
  source    = "Gallup",
  file_name = "cipo-337-E-1969-09_F1.sav",
  demographics = function(..d) {
    ..d %>% transmute(
      # age_cats <- age | AGE GROUP (IN YRS)
      age_cats = recode_values(as.numeric(..d[["age"]]), 1 ~ 1, 2:3 ~ 2, 4 ~ 3),
      # com_100 <- commsize | SIZE OF COMMUNITY
      com_100 = recode_values(as.numeric(..d[["commsize"]]), 1:2 ~ 1, 3:6 ~ 0),
      # com_500 <- commsize | SIZE OF COMMUNITY
      com_500 = recode_values(as.numeric(..d[["commsize"]]), 1 ~ 1, 2:6 ~ 0),
      # degree <- educ | EDUCATION COMPLETED
      degree = recode_values(as.numeric(..d[["educ"]]), 1:7 ~ 0, 8 ~ 1, 9 ~ 0),
      # gender <- sex | SEX
      gender = recode_values(as.numeric(..d[["sex"]]), 1 ~ 0, 2 ~ 1),
      # language_home <- mtongue | LANGUAGE SPOKEN IN HOME
      language_home = recode_values(as.numeric(..d[["mtongue"]]), 1 ~ 2, 2 ~ 1, 3 ~ 4),
      # language_var <- language_home | which source supplied language: 1 = spoken at home
      language_var = recode_values(as.numeric(language_home), 1:99 ~ 1),
      # occupation <- occhead | OCCUPATION OF HEAD OF HOUSE
      occupation = recode_values(as.numeric(..d[["occhead"]]), 0 ~ 8, 1 ~ 2, 2 ~ 1, 3:4 ~ 3, 5:6 ~ 4, 7 ~ 6, 8 ~ 99, 9 ~ 7, 10 ~ 9, 11 ~ 5),
      # province <- prov | RESIDENT PROVINCE
      province = recode_values(as.numeric(..d[["prov"]]), 1 ~ 12, 2 ~ 13, 3 ~ 10, 4 ~ 24, 5 ~ 35, 6 ~ 46, 7 ~ 47, 8 ~ 48, 9 ~ 59),
      # region <- prov | RESIDENT PROVINCE
      region = recode_values(as.numeric(..d[["prov"]]), 1:3 ~ 1, 4 ~ 2, 5 ~ 3, 6:8 ~ 4, 9 ~ 5),
      # religion <- religion | RELIGION
      religion = recode_values(as.numeric(..d[["religion"]]), 1 ~ 2, 2 ~ 3, 3 ~ 1, 4 ~ 4),
      # survey_mode <- assigned by hand | assigned by hand; not in the survey file
      survey_mode = rep(1, nrow(..d)),
      # union_household <- union | UNION MEMBERSHIP IN HOUSEHOLD
      union_household = recode_values(as.numeric(..d[["union"]]), 1 ~ 1, 2 ~ 0),
      # vote_choice <- lparty | VOTED FOR LAST FEDERAL ELECTION
      vote_choice = recode_values(as.numeric(..d[["lparty"]]), 0 ~ 99, 1 ~ 96, 2 ~ 97, 3 ~ 1, 4 ~ 2, 5 ~ 3, 6:7 ~ 4, 9 ~ 9, 11 ~ 98),
      # vote_intention <- nowparty | PRESENT PREFERRED POLITICAL PARTY
      vote_intention = recode_values(as.numeric(..d[["nowparty"]]), 0 ~ 97, 1 ~ 1, 2 ~ 2, 3 ~ 3, 4:5 ~ 4, 6 ~ 5, 7 ~ 9, 8 ~ 99, 9 ~ 98),
      # language <- language_home | language spoken at home
      language = in_range(language_home, 1, 99)
    )
  }
)

# cipo-338-E-1969-10_F1.sav -- Gallup, 16 demographic variables, 1 issue question
survey(
  survey_id = "cipo-338-E-1969-10_F1.sav",
