      # gender <- sex | SEX
      gender = recode_values(as.numeric(..d[["sex"]]), 1 ~ 0, 2 ~ 1),
      # mother_tongue <- mtongue | LANGUAGE OF CHILDHOOD
      mother_tongue = recode_values(as.numeric(..d[["mtongue"]]), 1 ~ 2, 2 ~ 1, 3 ~ 4),
      # occupation <- occhead | OCCUPATION OF HEAD OF HOUSE
      occupation = recode_values(as.numeric(..d[["occhead"]]), 0 ~ 8, 1 ~ 2, 2 ~ 1, 3:4 ~ 3, 5:6 ~ 4, 7 ~ 6, 8 ~ 99, 9 ~ 7, 10 ~ 9, 11 ~ 5),
      # province <- prov | RESIDENT PROVINCE
      province = recode_values(as.numeric(..d[["prov"]]), 0 ~ 11, 1 ~ 12, 2 ~ 13, 3 ~ 10, 4 ~ 24, 5 ~ 35, 6 ~ 46, 7 ~ 47, 8 ~ 48, 9 ~ 59),
      # region <- prov | RESIDENT PROVINCE
      region = recode_values(as.numeric(..d[["prov"]]), 1:3 ~ 1, 4 ~ 2, 5 ~ 3, 6:8 ~ 4, 9 ~ 5),
      # religion <- religion | RELIGION
      religion = recode_values(as.numeric(..d[["religion"]]), 1 ~ 2, 2 ~ 3, 3 ~ 1, 4 ~ 4),
      # survey_mode <- assigned by hand | assigned by hand; not in the survey file
      survey_mode = rep(1, nrow(..d)),
      # union_household <- union | UNION MEMBERSHIP IN HOUSEHOLD
      union_household = recode_values(as.numeric(..d[["union"]]), 1 ~ 1, 2 ~ 0),
      # vote_choice <- lparty | VOTED FOR LAST FEDERAL ELECTION
      vote_choice = recode_values(as.numeric(..d[["lparty"]]), 0 ~ 99, 1 ~ 96, 2 ~ 97, 3 ~ 1, 4 ~ 2, 5 ~ 3, 6:7 ~ 4, 11 ~ 98),
      # vote_intention <- nowparty | PRESENT PREFERRED POLITICAL PARTY
      vote_intention = recode_values(as.numeric(..d[["nowparty"]]), 0 ~ 97, 1 ~ 1, 2 ~ 2, 3 ~ 3, 4:5 ~ 4, 6 ~ 5, 7 ~ 9, 8 ~ 99, 9 ~ 98),
      # language <- mother_tongue | mother tongue (no language-at-home question in this survey)
      language = in_range(mother_tongue, 1, 99),
      # language_var <- mother_tongue | which source supplied language: 2 = mother tongue
      language_var = recode_values(as.numeric(mother_tongue), 1:99 ~ 2)
    )
  },
  issues = function(d) {
    d %>% transmute(
      # Lower voting age to 18
      # q6: 1=APPROVE 2=DISAPPROVE 3=QUALIFIED 4=UNDECIDED
      gal_dpin_001 = recode_values(q6, 1 ~ 1, 2 ~ -1, 3 ~ 0, 4 ~ 9999)
    )
  }
)

