      # province <- prov | RESIDENT PROV. OF RESPONDENT
      province = recode_values(as.numeric(..d[["prov"]]), 2 ~ 12, 3 ~ 13, 4 ~ 10, 5 ~ 24, 6 ~ 35, 7 ~ 46, 8 ~ 47, 9 ~ 48, 10 ~ 59),
      # region <- prov | RESIDENT PROV. OF RESPONDENT
      region = recode_values(as.numeric(..d[["prov"]]), 2:4 ~ 1, 5 ~ 2, 6 ~ 3, 7:9 ~ 4, 10 ~ 5),
      # religion <- religion | RELIGION OF RESPONDENT
      religion = recode_values(as.numeric(..d[["religion"]]), 1 ~ 2, 2 ~ 1, 3 ~ 3, 4 ~ 4),
      # survey_mode <- assigned by hand | assigned by hand; not in the survey file
      survey_mode = rep(1, nrow(..d)),
      # union_household <- union | UNION MEMBERSHIP IN HOUSEHOLD
      union_household = recode_values(as.numeric(..d[["union"]]), 1 ~ 1, 2 ~ 0),
      # vote_choice <- lparty | PARTY VOTED FOR LAST FEDERAL ELECTION
      vote_choice = recode_values(as.numeric(..d[["lparty"]]), 0 ~ 99, 1 ~ 96, 2 ~ 97, 3 ~ 1, 4 ~ 2, 5 ~ 3, 7 ~ 4, 8 ~ 5, 9 ~ 9),
      # vote_intention <- nowparty | PRESENT PREFERRED POLITICAL PARTY
      vote_intention = recode_values(as.numeric(..d[["nowparty"]]), 0 ~ 97, 1 ~ 2, 2 ~ 1, 3 ~ 3, 4:5 ~ 4, 6 ~ 5, 7 ~ 9, 8 ~ 99, 9 ~ 98),
      # language <- language_home | language spoken at home
