  demographics = function(..d) {
    ..d %>% transmute(
      # age <- birth | YEAR OF BIRTH (IN 1900s)
      age = recode_values(as.numeric(..d[["birth"]]), 1 ~ 80, 2 ~ 79, 3 ~ 78, 4 ~ 77, 5 ~ 76, 6 ~ 75, 7 ~ 74, 8 ~ 73, 9 ~ 72, 10 ~ 71, 11 ~ 70, 12 ~ 69, 13 ~ 68, 14 ~ 67, 15 ~ 66, 16 ~ 65, 17 ~ 64, 18 ~ 63, 19 ~ 62, 20 ~ 61, 21 ~ 60, 22 ~ 59, 23 ~ 58, 24 ~ 57, 25 ~ 56, 26 ~ 55, 27 ~ 54, 28 ~ 53, 29 ~ 52, 30 ~ 51, 31 ~ 50, 32 ~ 49, 33 ~ 48, 34 ~ 47, 35 ~ 46, 36 ~ 45, 37 ~ 44, 38 ~ 43, 39 ~ 42, 40 ~ 41, 41 ~ 40, 42 ~ 39, 43 ~ 38, 44 ~ 37, 45 ~ 36, 46 ~ 35, 47 ~ 34, 48 ~ 33, 49 ~ 32, 50 ~ 31, 51 ~ 30, 52 ~ 29, 53 ~ 28, 54 ~ 27, 55 ~ 26, 56 ~ 25, 57 ~ 24, 58 ~ 23, 59 ~ 22, 60 ~ 21, 61 ~ 20, 62 ~ 19, 63 ~ 18, 98 ~ 82),
      # age_cats <- age | constructed from continuous age
      age_cats = recode_values(as.numeric(age), 0:29 ~ 1, 30:49 ~ 2, 50:125 ~ 3),
      # degree <- educ | HIGHEST LEVEL OF EDUCATION
      degree = recode_values(as.numeric(..d[["educ"]]), 1:7 ~ 0, 8 ~ 1, 9 ~ 0),
