  source    = "Gallup",
  file_name = "cipo-486-3-E-1984-06_F1.sav",
  demographics = function(..d) {
    ..d %>% transmute(
      # age <- yrbirth | YEAR OF BIRTH (19--)
      age = recode_values(as.numeric(..d[["yrbirth"]]), 1 ~ 83, 2 ~ 82, 3 ~ 81, 4 ~ 80, 5 ~ 79, 6 ~ 78, 7 ~ 77, 8 ~ 76, 9 ~ 75, 10 ~ 74, 11 ~ 73, 12 ~ 72, 13 ~ 71, 14 ~ 70, 15 ~ 69, 16 ~ 68, 17 ~ 67, 18 ~ 66, 19 ~ 65, 20 ~ 64, 21 ~ 63, 22 ~ 62, 23 ~ 61, 24 ~ 60, 25 ~ 59, 26 ~ 58, 27 ~ 57, 28 ~ 56, 29 ~ 55, 30 ~ 54, 31 ~ 53, 32 ~ 52, 33 ~ 51, 34 ~ 50, 35 ~ 49, 36 ~ 48, 37 ~ 47, 38 ~ 46, 39 ~ 45, 40 ~ 44, 41 ~ 43, 42 ~ 42, 43 ~ 41, 44 ~ 40, 45 ~ 39, 46 ~ 38, 47 ~ 37, 48 ~ 36, 49 ~ 35, 50 ~ 34, 51 ~ 33, 52 ~ 32, 53 ~ 31, 54 ~ 30, 55 ~ 29, 56 ~ 28, 57 ~ 27, 58 ~ 26, 59 ~ 25, 60 ~ 24, 61 ~ 23, 62 ~ 22, 63 ~ 21, 64 ~ 20, 65 ~ 19, 66 ~ 18, 98 ~ 85),
      # age_cats <- age | constructed from continuous age
      age_cats = recode_values(as.numeric(age), 0:29 ~ 1, 30:49 ~ 2, 50:125 ~ 3),
      # com_100 <- commsize | SIZE OF COMMUNITY
      com_100 = recode_values(as.numeric(..d[["commsize"]]), 1:2 ~ 1, 3:6 ~ 0),
      # com_500 <- commsize | SIZE OF COMMUNITY
      com_500 = recode_values(as.numeric(..d[["commsize"]]), 1 ~ 1, 2:6 ~ 0),
      # degree <- educ | EDUCATION COMPLETED
      degree = recode_values(as.numeric(..d[["educ"]]), 1:7 ~ 0, 8 ~ 1, 9 ~ 0),
      # gender <- sex | SEX
      gender = recode_values(as.numeric(..d[["sex"]]), 1 ~ 0, 2 ~ 1),
      # mother_tongue <- mtongue | LANGUAGE OF CHILDHOOD
      mother_tongue = recode_values(as.numeric(..d[["mtongue"]]), 1 ~ 2, 2 ~ 1, 3 ~ 4),
      # occupation <- occup | OCCUPATION
      occupation = recode_values(as.numeric(..d[["occup"]]), 0 ~ 8, 1 ~ 2, 2 ~ 1, 3:4 ~ 3, 5:6 ~ 4, 7 ~ 8, 8 ~ 99, 9 ~ 9),
      # province <- prov | RESIDENT PROVINCE
      province = recode_values(as.numeric(..d[["prov"]]), 0 ~ 10, 1 ~ 11, 2 ~ 12, 3 ~ 13, 4 ~ 24, 5 ~ 35, 6 ~ 46, 7 ~ 47, 8 ~ 48, 9 ~ 59),
      # region <- prov | RESIDENT PROVINCE
      region = recode_values(as.numeric(..d[["prov"]]), 0:3 ~ 1, 4 ~ 2, 5 ~ 3, 6:8 ~ 4, 9 ~ 5),
      # religion <- religion | RELIGION
      religion = recode_values(as.numeric(..d[["religion"]]), 1 ~ 2, 2 ~ 3, 3 ~ 1, 4 ~ 4, 5 ~ 5),
      # survey_mode <- assigned by hand | assigned by hand; not in the survey file
      survey_mode = rep(1, nrow(..d)),
      # union_household <- union | UNION MEMBERSHIP IN HOUSEHOLD
      union_household = recode_values(as.numeric(..d[["union"]]), 1:2 ~ 1, 3 ~ 0, 5 ~ 1),
      # vote_choice <- lparty | VOTED FOR LAST FEDERAL ELECTION
      vote_choice = recode_values(as.numeric(..d[["lparty"]]), 0 ~ 98, 1 ~ 96, 2 ~ 97, 3 ~ 1, 4 ~ 2, 5 ~ 3, 6:7 ~ 4, 8 ~ 9, 9 ~ 99),
      # vote_intention <- nowparty | PRESENT PREFERRED POLITICAL PARTY
      vote_intention = recode_values(as.numeric(..d[["nowparty"]]), 1 ~ 1, 2 ~ 2, 3 ~ 3, 4 ~ 4, 6 ~ 9, 7 ~ 99, 8 ~ 98, 9 ~ 97),
      # language <- mother_tongue | mother tongue (no language-at-home question in this survey)
      language = in_range(mother_tongue, 1, 99),
      # language_var <- mother_tongue | which source supplied language: 2 = mother tongue
      language_var = recode_values(as.numeric(mother_tongue), 1:99 ~ 2)
