      age_cats = recode_values(as.numeric(age), 0:29 ~ 1, 30:49 ~ 2, 50:125 ~ 3),
      # com_100 <- commsize | SIZE OF COMMUNITY
      com_100 = recode_values(as.numeric(..d[["commsize"]]), 1:2 ~ 1, 3:6 ~ 0),
      # com_500 <- commsize | SIZE OF COMMUNITY
      com_500 = recode_values(as.numeric(..d[["commsize"]]), 1 ~ 1, 2:6 ~ 0),
      # degree <- educ | EDUCATION COMPLETED
      degree = recode_values(as.numeric(..d[["educ"]]), 1:7 ~ 0, 8 ~ 1),
      # gender <- sex | SEX
      gender = recode_values(as.numeric(..d[["sex"]]), 1 ~ 0, 2 ~ 1),
      # mother_tongue <- mtongue | LANGUAGE OF CHILDHOOD
      mother_tongue = recode_values(as.numeric(..d[["mtongue"]]), 1 ~ 2, 2 ~ 1, 3 ~ 4),
      # occupation <- occup | OCCUPATION
      occupation = recode_values(as.numeric(..d[["occup"]]), 0 ~ 8, 1 ~ 2, 2 ~ 1, 3:4 ~ 3, 5:6 ~ 4, 7 ~ 8, 8 ~ 99, 9 ~ 9),
      # province <- prov | RESIDENT PROVINCE
      province = recode_values(as.numeric(..d[["prov"]]), 0 ~ 10, 1 ~ 11, 2 ~ 12, 3 ~ 13, 4 ~ 24, 5 ~ 35, 6 ~ 46, 7 ~ 47, 8 ~ 48, 9 ~ 59),
      # region <- prov | RESIDENT PROVINCE
      region = recode_values(as.numeric(..d[["prov"]]), 0:3 ~ 1, 4 ~ 2, 5 ~ 3, 6:8 ~ 4, 9 ~ 5),
      # religion <- religion | RELIGION
