      survey_mode = rep(1, nrow(..d)),
      # union_household <- union | UNION MEMBERSHIP IN HOUSEHOLD
      union_household = recode_values(as.numeric(..d[["union"]]), 1:2 ~ 1, 3 ~ 0, 5 ~ 1),
      # vote_choice <- lparty | VOTED FOR LAST FEDERAL ELECTION
      vote_choice = recode_values(as.numeric(..d[["lparty"]]), 0 ~ 98, 1 ~ 96, 2 ~ 97, 3 ~ 1, 4 ~ 2, 5 ~ 3, 6:7 ~ 4, 8 ~ 9, 9 ~ 99),
      # vote_intention <- nowparty | PRESENT PREFERRED POLITICAL PARTY
      vote_intention = recode_values(as.numeric(..d[["nowparty"]]), 1 ~ 1, 2 ~ 2, 3 ~ 3, 4:5 ~ 4, 6 ~ 9, 7 ~ 99, 8 ~ 98, 9 ~ 97),
      # language <- mother_tongue | mother tongue (no language-at-home question in this survey)
      language = in_range(mother_tongue, 1, 99),
      # language_var <- mother_tongue | which source supplied language: 2 = mother tongue
      language_var = recode_values(as.numeric(mother_tongue), 1:99 ~ 2)
    )
  },
  issues = function(d) {
    d %>% transmute(
      # Labour unions too powerful
      # q13b: 1=TOO POWERFUL 2=NOT POWERFUL ENOUGH 3=ABOUT RIGHT 4=DON'T KNOW 5=NOT STATED
      bri_econ_003 = recode_values(q13b, 1 ~ 1, 2 ~ -1, 3 ~ 0, c(4, 5) ~ 9999),

      # Buy back 51% control of US firms
      # q3: 1=APPROVE 2=DISAPPROVE 3=QUALIFIED 4=DON'T KNOW 5=NOT STATED
      gal_econ_008 = recode_values(q3, 1 ~ 1, 2 ~ -1, 3 ~ 0, c(4, 5) ~ 9999),

      # US capital in Cda: enough or more
      # q2: 1=ENOUGH NOW 2=LIKE TO SEE MORE 3=DON'T KNOW 4=NOT STATED
      gal_econ_003 = recode_values(q2, 1 ~ 0, 2 ~ 1, c(3, 4) ~ 9999),

      # Unions a good/bad thing for Cda
      # q13a: 1=GOOD THING 2=BAD THING 3=DON'T KNOW 4=NOT STATED
      gal_econ_014 = recode_values(q13a, 1 ~ 1, 2 ~ 0, c(3, 4) ~ 9999)
    )
  }
)

