# cipo-489-2-E-1984-09_F1.sav -- Gallup, 12 demographic variables
survey(
  survey_id = "cipo-489-2-E-1984-09_F1.sav",
  source    = "Gallup",
  file_name = "cipo-489-2-E-1984-09_F1.sav",
  demographics = function(..d) {
    ..d %>% transmute(
      # age <- birth | YEAR OF BIRTH (19--)
      age = recode_values(as.numeric(..d[["birth"]]), 1 ~ 83, 2 ~ 82, 3 ~ 81, 4 ~ 80, 5 ~ 79, 6 ~ 78, 7 ~ 77, 8 ~ 76, 9 ~ 75, 10 ~ 74, 11 ~ 73, 12 ~ 72, 13 ~ 71, 14 ~ 70, 15 ~ 69, 16 ~ 68, 17 ~ 67, 18 ~ 66, 19 ~ 65, 20 ~ 64, 21 ~ 63, 22 ~ 62, 23 ~ 61, 24 ~ 60, 25 ~ 59, 26 ~ 58, 27 ~ 57, 28 ~ 56, 29 ~ 55, 30 ~ 54, 31 ~ 53, 32 ~ 52, 33 ~ 51, 34 ~ 50, 35 ~ 49, 36 ~ 48, 37 ~ 47, 38 ~ 46, 39 ~ 45, 40 ~ 44, 41 ~ 43, 42 ~ 42, 43 ~ 41, 44 ~ 40, 45 ~ 39, 46 ~ 38, 47 ~ 37, 48 ~ 36, 49 ~ 35, 50 ~ 34, 51 ~ 33, 52 ~ 32, 53 ~ 31, 54 ~ 30, 55 ~ 29, 56 ~ 28, 57 ~ 27, 58 ~ 26, 59 ~ 25, 60 ~ 24, 61 ~ 23, 62 ~ 22, 63 ~ 21, 64 ~ 20, 65 ~ 19, 66 ~ 18, 98 ~ 85),
      # age_cats <- age | constructed from continuous age
      age_cats = recode_values(as.numeric(age), 0:29 ~ 1, 30:49 ~ 2, 50:125 ~ 3),
      # degree <- educ | LAST SCHOOL ATTENDED
      degree = recode_values(as.numeric(..d[["educ"]]), 1:7 ~ 0, 8 ~ 1, 9 ~ 0),
      # gender <- gend | GENDER
      gender = recode_values(as.numeric(..d[["gend"]]), 1 ~ 0, 2 ~ 1),
      # mother_tongue <- mtongue | MOTHER TONGUE
      mother_tongue = recode_values(as.numeric(..d[["mtongue"]]), 1 ~ 2, 2 ~ 1, 3 ~ 4),
      # occupation <- occ or occhh | OCCUPATION
      occupation = coalesce(recode_values(as.numeric(..d[["occ"]]), 0 ~ 99, 1 ~ 2, 2 ~ 1, 3:4 ~ 3, 5:6 ~ 4, 7 ~ 8, 8 ~ 99, 9 ~ 9), recode_values(as.numeric(..d[["occhh"]]), 0 ~ 99, 1 ~ 2, 2 ~ 1, 3:4 ~ 3, 5:6 ~ 4, 7 ~ 8, 8 ~ 99, 9 ~ 9)),
      # religion <- rel | RELIGIOUS PREFERENCE
      religion = recode_values(as.numeric(..d[["rel"]]), 1 ~ 2, 2 ~ 3, 3 ~ 1, 4 ~ 4),
      # survey_mode <- assigned by hand | assigned by hand; not in the survey file
      survey_mode = rep(1, nrow(..d)),
      # union_household <- union | YOU OR SPOUSE MEMBER OF A UNION
      union_household = recode_values(as.numeric(..d[["union"]]), 1:2 ~ 1, 3 ~ 0, 5 ~ 1),
      # vote_choice <- q2 | ON SEPT 4 PARTY YOU VOTED FOR
      vote_choice = recode_values(as.numeric(..d[["q2"]]), 1 ~ 2, 2 ~ 1, 3 ~ 3, 4 ~ 9, 5 ~ 96, 6 ~ 98),
      # language <- mother_tongue | mother tongue (no language-at-home question in this survey)
      language = in_range(mother_tongue, 1, 99),
      # language_var <- mother_tongue | which source supplied language: 2 = mother tongue
      language_var = recode_values(as.numeric(mother_tongue), 1:99 ~ 2)
    )
  }
)

