      # occupation <- occ | OCCUPATION
      occupation = recode_values(as.numeric(..d[["occ"]]), 0 ~ 99, 1 ~ 2, 2 ~ 1, 3:4 ~ 3, 5:6 ~ 4, 7 ~ 8, 8 ~ 99, 9 ~ 9),
      # province <- prov | PROVINCE
      province = recode_values(as.numeric(..d[["prov"]]), 0 ~ 10, 1 ~ 11, 2 ~ 12, 3 ~ 13, 4 ~ 24, 5 ~ 35, 6 ~ 46, 7 ~ 47, 8 ~ 48, 9 ~ 59),
      # region <- prov | PROVINCE
      region = recode_values(as.numeric(..d[["prov"]]), 0:3 ~ 1, 4 ~ 2, 5 ~ 3, 6:8 ~ 4, 9 ~ 5),
      # religion <- rel | RELIGIOUS PREFERENCE
      religion = recode_values(as.numeric(..d[["rel"]]), 1 ~ 2, 2 ~ 3, 3 ~ 1, 4 ~ 4),
