      # union_household <- union | YOU OR SPOUSE MEMBER OF A UNION
      union_household = recode_values(as.numeric(..d[["union"]]), 1:2 ~ 1, 3 ~ 0, 5 ~ 1),
      # vote_choice <- q18 | SEPT 4 1984 ELECTION, VOTED FOR:
      vote_choice = recode_values(as.numeric(..d[["q18"]]), 1 ~ 96, 2 ~ 97, 3 ~ 1, 4 ~ 2, 5 ~ 3, 8 ~ 9, 9 ~ 99),
      # vote_intention <- q17 | IF ELECTION HELD TODAY, VOTE FOR:
