      language_var = recode_values(as.numeric(mother_tongue), 1:99 ~ 2)
    )
  },
  issues = function(d) {
    d %>% transmute(
      # Fed govt handling economy properly
      # hec: 1=YES 2=NO 3=DONT KNOW 4=REFUSED
      bri_econ_002 = recode_values(hec, 1 ~ 1, 2 ~ 0, c(3, 4) ~ 9999),

