  issues = function(d) {
    d %>% transmute(
      # Top priority: deficit vs unemployment
      # defop: 1=REDUCE DEFICIT 2=REDUCE UNEMPLOY. 3=NEITHER 4=BOTH 5=DONT KNOW 6=REFUSED
